import { Effect } from "effect";

export interface DefinedOperation<
	Descriptor,
	Args extends readonly unknown[],
	Result,
	Error,
> {
	readonly descriptor: Descriptor;
	readonly effect: (...args: Args) => Effect.Effect<Result, Error>;
	execute(...args: Args): Promise<Result>;
}

/**
 * Build one operation triple from a descriptor and a generator body.
 *
 * The tracing span derives from the descriptor (`operations.<id>`), so span
 * names cannot drift from operation identity. `execute` runs the same effect
 * value instead of closing over the partially built operation object, and the
 * `Effect.runPromise` edge rejects `R` at compile time: only `R = never`
 * effects satisfy the body contract.
 */
export function defineOperation<
	const Descriptor extends { readonly id: string },
	const Args extends readonly unknown[],
	Result,
	Error,
>(
	descriptor: Descriptor,
	body: (...args: Args) => Effect.fn.Return<Result, Error>,
): DefinedOperation<Descriptor, Args, Result, Error> {
	const effect = Effect.fn(`operations.${descriptor.id}`)(body);
	return {
		descriptor,
		effect,
		execute(...args: Args) {
			return Effect.runPromise(effect(...args));
		},
	};
}

