function expressionReferences(
	node: ESTree.Expression | ESTree.Pattern | ESTree.RestElement | null | undefined,
	name: string,
): boolean {
	if (node === null || node === undefined) return false;
	if (node.type === "Identifier") return node.name === name;
	return false;
